use crate::*;
use std::io::{Read,Write};
pub fn estimate(core:&Core,id:&str,args:&Value)->Result<Value>{let mut include=vec!["options","mods","shaderpacks"];if args["includeConfig"]!=false{include.push("config");}if args["includeLocalization"]!=false{include.push("resourcepacks");}let files=pack_export::files(core,&json!({"id":id,"include":include,"selectionVersion":1}))?;let root=core.instance(id)?;let bytes=files.iter().map(|f|std::fs::metadata(root.join(f)).map(|v|v.len()).unwrap_or(0)).sum::<u64>();Ok(json!({"estimatedBytes":bytes,"files":files.len(),"note":"ZIP 压缩与在线资源索引会改变最终体积。","requiresConfirmation":true}))}
pub async fn run(core:&Core,id:&str,path:&Path,args:&Value)->Result<Value>{
 super::policy::absolute(&core.root,path)?;std::fs::create_dir_all(path.parent().ok_or("导出路径无效")?).map_err(err)?;
 let mut include=vec!["options","mods"];if args["includeConfig"]!=false{include.push("config");}if args["includeLocalization"]!=false{include.push("resourcepacks");}include.push("shaderpacks");
 pack_export::export(core,&json!({"id":id,"path":path,"format":"mrpack","bundleResources":false,"selectionVersion":1,"include":include})).await?;
 let instance=read_json(&core.instance(id)?.join("kxl.json"))?;let lock=read_json(&core.instance(id)?.join("installed-projects.json")).unwrap_or_else(|_|json!({}));
 let mut original=zip::ZipArchive::new(std::fs::File::open(path).map_err(err)?).map_err(err)?;let staged=path.with_extension(format!("{}.tmp",uuid::Uuid::new_v4()));let mut writer=zip::ZipWriter::new(std::fs::File::create(&staged).map_err(err)?);let options=zip::write::SimpleFileOptions::default().compression_method(zip::CompressionMethod::Deflated);let mut skipped=Vec::new();
 for i in 0..original.len(){core.stopped()?;let mut file=original.by_index(i).map_err(err)?;let name=file.name().to_owned();if file.is_dir(){continue;}if !safe_archive_path(&name){skipped.push(name);continue;}let mut bytes=Vec::new();if file.size()>super::policy::MAX_BYTES{return Err("导出单文件超过预算".into());}file.read_to_end(&mut bytes).map_err(err)?;if name.starts_with("overrides/config/")&&std::str::from_utf8(&bytes).ok().is_some_and(|v|regex::Regex::new(r#"(?i)(?:password|access[_-]?token|refresh[_-]?token|api[_-]?key)[\s\"':=]+[^\s\",;}]+"#).unwrap().is_match(v)){skipped.push(name);continue;}writer.start_file(name,options).map_err(err)?;writer.write_all(&bytes).map_err(err)?;}
 if args["includeReadme"]!=false{writer.start_file("README.md",options).map_err(err)?;writer.write_all(format!("# {}\n\nMinecraft {} / {}\n\n由 Kynex Launcher 整合包工坊导出。导入前核对 Java 与内存需求。AI 汉化属于机器翻译，可能有误；未包含凭据、日志和存档。\n",instance["name"].as_str().unwrap_or("整合包"),instance["version"].as_str().unwrap_or(""),instance["loader"].as_str().unwrap_or("")).as_bytes()).map_err(err)?;}
 if args["includeModList"]!=false{writer.start_file("modlist.html",options).map_err(err)?;let rows=lock.as_object().into_iter().flatten().map(|(id,v)|format!("<li>{} · {}</li>",escape(v["name"].as_str().unwrap_or(id)),escape(v["source"].as_str().unwrap_or("未知来源")))).collect::<Vec<_>>().join("\n");writer.write_all(format!("<!doctype html><meta charset=\"utf-8\"><title>模组清单</title><h1>模组清单</h1><ul>{rows}</ul>").as_bytes()).map_err(err)?;}
 if args["includeLicense"]!=false{writer.start_file("THIRD-PARTY-NOTICES",options).map_err(err)?;writer.write_all("模组、资源包和光影的版权属于各自作者。请遵守各项目的发行许可证、署名与分发限制。本清单不授予额外分发权限。机器补译不代表模组作者或 CFPA 社区的翻译质量。\n".as_bytes()).map_err(err)?;}
 writer.finish().map_err(err)?;drop(original);validate(&staged)?;std::fs::rename(&staged,path).map_err(err)?;Ok(json!({"exported":true,"file":path.file_name().unwrap_or_default().to_string_lossy(),"location":"当前游戏目录 exports/","skippedSensitiveFiles":skipped,"bytes":std::fs::metadata(path).map_err(err)?.len()}))
}
fn escape(s:&str)->String{s.replace('&',"&amp;").replace('<',"&lt;").replace('>',"&gt;").replace('"',"&quot;")}
pub fn safe_archive_path(s:&str)->bool{!s.starts_with('/')&&!s.contains('\\')&&!s.contains(':')&&!s.split('/').any(|p|p==".."||p=="."||["logs","crash-reports","saves"].contains(&p))&&!s.to_lowercase().contains("credential")&&!s.to_lowercase().contains("accounts.json")&&!s.ends_with(".kxl-agent-backup")}
pub fn validate(path:&Path)->Result<()>{let mut zip=zip::ZipArchive::new(std::fs::File::open(path).map_err(err)?).map_err(err)?;if zip.len()>30000{return Err("导出文件数量超过限制".into());}for name in zip.file_names(){if !safe_archive_path(name){return Err("导出包含不允许的路径或私密数据".into());}}let manifest:Value=serde_json::from_reader(zip.by_name("modrinth.index.json").map_err(|_|"导出包缺少 mrpack manifest")?).map_err(err)?;if manifest["formatVersion"]!=1||manifest["game"]!="minecraft"{return Err("mrpack manifest 格式无效".into());}for file in manifest["files"].as_array().into_iter().flatten(){if !safe_archive_path(string(file,"path")?)||file["hashes"]["sha1"].as_str().is_none_or(|s|s.len()!=40){return Err("导出资源路径或哈希无效".into());}for url in file["downloads"].as_array().into_iter().flatten(){super::policy::url(url.as_str().ok_or("资源链接无效")?)?;}}Ok(())}
#[cfg(test)]mod tests{use super::*;#[test]fn privacy_paths(){for path in ["overrides/logs/latest.log","overrides/saves/World/level.dat","../tokens.json","C:/file","overrides/accounts.json","overrides/config/x.kxl-agent-backup"]{assert!(!safe_archive_path(path));}assert!(safe_archive_path("overrides/resourcepacks/KXL-AI-Localization/assets/a/lang/zh_cn.json"));assert_eq!(escape("<x>"),"&lt;x&gt;");}
 #[tokio::test]async fn mrpack_contains_metadata_and_localization_without_private_data(){let t=tempfile::tempdir().unwrap();let c=Core::new(t.path().join("game"),Arc::new(|_|{})).unwrap();let root=c.instance("x").unwrap();write_json(&root.join("kxl.json"),&json!({"id":"x","name":"测试包","version":"1.20.1","loader":"vanilla","settings":{"isolation":"all"}})).unwrap();write_json(&root.join("version.json"),&json!({"id":"1.20.1"})).unwrap();for(path,text)in[("config/ok.json","{\"enabled\":true}"),("config/private.json","{\"api_key\":\"DONT_EXPORT\"}"),("logs/latest.log","PRIVATE_LOG"),("saves/World/level.dat","PRIVATE_WORLD"),("resourcepacks/KXL-AI-Localization/pack.mcmeta","{\"pack\":{\"pack_format\":15,\"description\":\"机器补译\"}}"),("options.txt","lang:zh_cn\n")]{let f=root.join(path);std::fs::create_dir_all(f.parent().unwrap()).unwrap();std::fs::write(f,text).unwrap();}let dest=c.root.join("exports/test.mrpack");run(&c,"x",&dest,&json!({})).await.unwrap();validate(&dest).unwrap();let mut z=zip::ZipArchive::new(std::fs::File::open(dest).unwrap()).unwrap();let names=z.file_names().map(str::to_owned).collect::<Vec<_>>();for name in ["README.md","modlist.html","THIRD-PARTY-NOTICES","overrides/config/ok.json","overrides/options.txt","overrides/resourcepacks/KXL-AI-Localization/pack.mcmeta"]{assert!(names.iter().any(|n|n==name),"missing {name}");}for i in 0..z.len(){let mut s=Vec::new();z.by_index(i).unwrap().read_to_end(&mut s).unwrap();let s=String::from_utf8_lossy(&s);for token in ["DONT_EXPORT","PRIVATE_LOG","PRIVATE_WORLD"]{assert!(!s.contains(token));}}}
}
